import React, { useState } from 'react';
import { AVAILABLE_FIELDS_STYLES, TYPOGRAPHY } from '../../constants/uiStyles';

/**
 * Available Fields/Tags Section
 * 
 * Shows available fields from upstream nodes that can be copied to clipboard.
 * Use "Available Fields" for data nodes, "Available Tags" for template nodes.
 * 
 * @param {array} fields - Array of field names
 * @param {string} title - Section title ('Available Fields' or 'Available Tags')
 * @param {string} color - Node color
 * @param {function} onCopy - Callback when a field is clicked (receives field name)
 */
export const AvailableFieldsSection = ({
    fields = [],
    title = 'Available Fields',
    color = 'amber',
    onCopy,
    selectedFields = [],
    helperText = 'Click to copy',
    readOnly = false,
}) => {
    const [isExpanded, setIsExpanded] = useState(false);
    if (fields.length === 0) return null;

    const toFieldString = (field) => {
        if (typeof field === 'string') return field;
        if (field && typeof field === 'object' && typeof field.label === 'string') return field.label;
        return String(field ?? '');
    };

    const copyToClipboard = (field) => {
        if (readOnly) return;
        // Remove asterisk marker if present (for modified fields)
        const cleanField = toFieldString(field).replace(/\s*\*\s*$/, '').trim();

        if (onCopy) {
            onCopy(cleanField);
        } else {
            // Default behavior: copy as {{field}}
            navigator.clipboard.writeText(`{{${cleanField}}}`);
        }
    };

    return (
        <div className={`mx-4 mt-3 p-2 bg-${color}-50/50 dark:bg-${color}-900/20 rounded-lg border border-${color}-100 dark:border-white/5 ${readOnly ? 'opacity-75' : ''}`}>
            <div
                className={`flex items-center justify-between select-none ${readOnly ? 'cursor-default' : 'cursor-pointer'}`}
                onClick={() => !readOnly && setIsExpanded(!isExpanded)}
            >
                <div className="flex items-center gap-1.5">
                    <svg className={`w-3 h-3 text-${color}-400 transition-transform duration-200 ${isExpanded ? 'rotate-90' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                    </svg>
                    <label className={`text-[10px] font-bold text-${color}-600 dark:text-${color}-400 uppercase tracking-wider cursor-pointer`}>
                        {title}
                        <span className="ml-1.5 opacity-60">({fields.length})</span>
                    </label>
                </div>
                {isExpanded && <span className={TYPOGRAPHY.HELPER.className}>{helperText}</span>}
            </div>

            {isExpanded && (
                <div className="flex flex-wrap gap-1.5 mt-2 pl-4">
                    {fields.map((field, index) => {
                        const displayField = toFieldString(field);
                        const cleanField = displayField.replace(/\s*\*\s*$/, '').trim();
                        const isSelected = selectedFields.includes(cleanField);

                        return (
                            <button
                                type="button"
                                key={`${cleanField}-${index}`}
                                disabled={readOnly}
                                onClick={() => copyToClipboard(field)}
                                className={`px-2 py-0.5 rounded border text-[10px] font-mono transition-all ${readOnly ? 'cursor-not-allowed opacity-60' : 'cursor-pointer'} ${isSelected
                                        ? `bg-${color}-500 border-${color}-600 text-white shadow-sm ring-1 ring-${color}-300 dark:ring-${color}-700`
                                        : `bg-white dark:bg-slate-800 border-${color}-200 dark:border-${color}-700 text-${color}-700 dark:text-${color}-300 hover:bg-${color}-50 dark:hover:bg-${color}-900/30 hover:border-${color}-300`
                                    }`}
                                title={onCopy ? cleanField : `{{${cleanField}}}`}
                            >
                                {displayField}
                            </button>
                        );
                    })}
                </div>
            )}
        </div>
    );
};
