import { useState, useEffect, useRef, useLayoutEffect } from 'react';

/**
 * Standard behaviour for Voodflow flow nodes (expand/collapse, connection, collapsed view).
 *
 * @param {string} nodeId
 * @param {object} nodeData - React Flow node data
 * @param {function} getEdges
 * @param {function} setNodes
 * @param {boolean} isTrigger - Triggers have no inputs and are treated as always "connected"
 */
export const useStandardNodeBehavior = (nodeId, nodeData, getEdges, setNodes, isTrigger = false) => {
    // New nodes start expanded
    const [isExpanded, setIsExpanded] = useState(
        nodeData.isExpanded ?? (nodeData.isNew ?? true)
    );

    // State for connection status (reactive)
    const [isConnected, setIsConnected] = useState(() => {
        const edges = getEdges();
        return edges.some(edge => edge.target === nodeId);
    });

    const [isOutputConnected, setIsOutputConnected] = useState(() => {
        const edges = getEdges();
        return edges.some(edge => edge.source === nodeId);
    });

    // Track previous connection state
    const wasConnected = useRef(isConnected);

    // `getEdges` from useReactFlow() often changes identity every render — do not list it as an effect dep
    // or the effect re-runs constantly during execution highlighting / drags (risk of update storms).
    const getEdgesRef = useRef(getEdges);
    useLayoutEffect(() => {
        getEdgesRef.current = getEdges;
    });

    // Listen for edge changes and update connection states
    useEffect(() => {
        const updateConnectionStates = () => {
            const currentEdges = getEdgesRef.current();
            const currentlyConnected = currentEdges.some(edge => edge.target === nodeId);
            const currentlyOutputConnected = currentEdges.some(edge => edge.source === nodeId);

            setIsConnected(currentlyConnected);
            setIsOutputConnected(currentlyOutputConnected);
        };

        // Update immediately on mount / when node id changes
        updateConnectionStates();

        window.addEventListener('voodflow:edges-changed', updateConnectionStates);
        return () => window.removeEventListener('voodflow:edges-changed', updateConnectionStates);
    }, [nodeId]);

    // Auto-expand when node gets connected while closed
    useEffect(() => {
        // If node was disconnected and is now connected
        if (!wasConnected.current && isConnected && !isExpanded) {
            setIsExpanded(true);

            // Save state to backend (skip when canvas is read-only — server rejects anyway).
            const workflowReadOnly = Boolean(nodeData.workflowReadOnly)
                || (typeof window !== 'undefined' && window.__voodflowWorkflowReadOnly);
            if (!workflowReadOnly && nodeData.livewireId && window.Livewire) {
                const component = window.Livewire.find(nodeData.livewireId);
                if (component) {
                    component.call('updateNodeConfig', {
                        nodeId: nodeId,
                        isExpanded: true
                    });
                }
            }

            // Update ReactFlow
            setNodes((nds) => nds.map((node) => {
                if (node.id === nodeId) {
                    return {
                        ...node,
                        data: {
                            ...node.data,
                            isExpanded: true,
                            isNew: false
                        }
                    };
                }
                return node;
            }));
        }

        wasConnected.current = isConnected;
    }, [isConnected, isExpanded, nodeId, nodeData.livewireId, setNodes]);

    // Manual expand/collapse
    const toggleExpansion = () => {
        const newExpandedState = !isExpanded;
        setIsExpanded(newExpandedState);

        const workflowReadOnly = Boolean(nodeData.workflowReadOnly)
            || (typeof window !== 'undefined' && window.__voodflowWorkflowReadOnly);
        if (!workflowReadOnly && nodeData.livewireId && window.Livewire) {
            const component = window.Livewire.find(nodeData.livewireId);
            if (component) {
                component.call('updateNodeConfig', {
                    nodeId: nodeId,
                    isExpanded: newExpandedState
                });
            }
        }

        // Update React Flow state
        setNodes((nds) => nds.map((node) => {
            if (node.id === nodeId) {
                return {
                    ...node,
                    data: {
                        ...node.data,
                        isExpanded: newExpandedState,
                        isNew: false
                    }
                };
            }
            return node;
        }));
    };

    // Configuration heuristic: description or node-specific config.
    // Triggers: also schedule_type / eventClass. Ignore webhookUrl for ReceiveWebhookNode.
    // Custom labels alone do not count as "configured" for triggers.
    const hasConfiguration = isTrigger
        ? Boolean(
            nodeData.description ||
            (nodeData.config && nodeData.config.schedule_type) ||
            nodeData.eventClass
        )
        : Boolean(
            nodeData.description ||
            nodeData.label !== nodeData.defaultLabel
        );

    // Logo: triggers when not configured; other nodes only when there is no incoming edge.
    // If a node is already connected on its input, do not show the logo/"Connect data" placeholder
    // even if it was just created.
    const shouldShowLogo = isTrigger
        ? !hasConfiguration
        : !isConnected;

    return {
        isExpanded,
        toggleExpansion,
        isConnected,
        isOutputConnected,
        shouldShowLogo,
        hasConfiguration,
        isTrigger
    };
};
