/**
 * Field Data Types for Voodflow
 * 
 * This enum defines all supported data types and their properties,
 * including which operators are appropriate for each type.
 */

import COMPARISON_OPERATORS from './operators';

export const FIELD_DATA_TYPES = {
    STRING: 'string',
    NUMBER: 'number',
    INTEGER: 'integer',
    FLOAT: 'float',
    BOOLEAN: 'boolean',
    DATE: 'date',
    DATETIME: 'datetime',
    TIME: 'time',
    ARRAY: 'array',
    OBJECT: 'object',
    JSON: 'json',
    EMAIL: 'email',
    URL: 'url',
    UUID: 'uuid',
};

export const DATE_PARTS = {
    YEAR: 'year',
    MONTH: 'month',
    DAY: 'day',
    HOUR: 'hour',
    MINUTE: 'minute',
};

export const DATE_PART_LABELS = {
    [DATE_PARTS.YEAR]: 'Year',
    [DATE_PARTS.MONTH]: 'Month',
    [DATE_PARTS.DAY]: 'Day',
    [DATE_PARTS.HOUR]: 'Hour',
    [DATE_PARTS.MINUTE]: 'Minute',
};

export const TIME_UNITS = {
    MINUTES: 'minutes',
    HOURS: 'hours',
    DAYS: 'days',
    WEEKS: 'weeks',
    MONTHS: 'months',
    YEARS: 'years',
};

export const TIME_UNIT_LABELS = {
    [TIME_UNITS.MINUTES]: 'Minutes',
    [TIME_UNITS.HOURS]: 'Hours',
    [TIME_UNITS.DAYS]: 'Days',
    [TIME_UNITS.WEEKS]: 'Weeks',
    [TIME_UNITS.MONTHS]: 'Months',
    [TIME_UNITS.YEARS]: 'Years',
};

/**
 * Get human-readable label for a data type
 */
export const getDataTypeLabel = (type) => {
    const labels = {
        [FIELD_DATA_TYPES.STRING]: 'Text',
        [FIELD_DATA_TYPES.NUMBER]: 'Number',
        [FIELD_DATA_TYPES.INTEGER]: 'Integer',
        [FIELD_DATA_TYPES.FLOAT]: 'Decimal',
        [FIELD_DATA_TYPES.BOOLEAN]: 'Boolean',
        [FIELD_DATA_TYPES.DATE]: 'Date',
        [FIELD_DATA_TYPES.DATETIME]: 'Date & Time',
        [FIELD_DATA_TYPES.TIME]: 'Time',
        [FIELD_DATA_TYPES.ARRAY]: 'Array',
        [FIELD_DATA_TYPES.OBJECT]: 'Object',
        [FIELD_DATA_TYPES.JSON]: 'JSON',
        [FIELD_DATA_TYPES.EMAIL]: 'Email',
        [FIELD_DATA_TYPES.URL]: 'URL',
        [FIELD_DATA_TYPES.UUID]: 'UUID',
    };
    return labels[type] || type;
};

/**
 * Get appropriate operators for a given data type
 */
export const getOperatorsForDataType = (dataType) => {
    const operatorsByType = {
        [FIELD_DATA_TYPES.STRING]: ['=', '!=', 'LIKE', 'NOT LIKE', 'STARTS WITH', 'ENDS WITH', 'IN', 'NOT IN', 'IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY'],
        [FIELD_DATA_TYPES.EMAIL]: ['=', '!=', 'LIKE', 'NOT LIKE', 'STARTS WITH', 'ENDS WITH', 'IN', 'NOT IN', 'IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY'],
        [FIELD_DATA_TYPES.URL]: ['=', '!=', 'LIKE', 'NOT LIKE', 'STARTS WITH', 'ENDS WITH', 'IN', 'NOT IN', 'IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY'],
        [FIELD_DATA_TYPES.UUID]: ['=', '!=', 'LIKE', 'NOT LIKE', 'IN', 'NOT IN', 'IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY'],

        [FIELD_DATA_TYPES.NUMBER]: ['=', '!=', '>', '<', '>=', '<=', 'IN', 'NOT IN', 'IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY'],
        [FIELD_DATA_TYPES.INTEGER]: ['=', '!=', '>', '<', '>=', '<=', 'IN', 'NOT IN', 'IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY'],
        [FIELD_DATA_TYPES.FLOAT]: ['=', '!=', '>', '<', '>=', '<=', 'IN', 'NOT IN', 'IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY'],

        [FIELD_DATA_TYPES.BOOLEAN]: ['=', '!=', 'IS NULL', 'IS NOT NULL', 'IS TRUE', 'IS FALSE', 'IS EMPTY', 'IS NOT EMPTY'],

        [FIELD_DATA_TYPES.DATE]: ['=', '!=', '>', '<', '>=', '<=', 'IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY', 'OLDER THAN', 'NEWER THAN', 'IN LAST', 'IN NEXT'],
        [FIELD_DATA_TYPES.DATETIME]: ['=', '!=', '>', '<', '>=', '<=', 'IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY', 'OLDER THAN', 'NEWER THAN', 'IN LAST', 'IN NEXT'],
        [FIELD_DATA_TYPES.TIME]: ['=', '!=', '>', '<', '>=', '<=', 'IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY'],

        [FIELD_DATA_TYPES.ARRAY]: ['IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY'],
        [FIELD_DATA_TYPES.JSON]: ['IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY'],
        [FIELD_DATA_TYPES.OBJECT]: ['IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY'],
    };

    const allowedOperatorValues = operatorsByType[dataType] || operatorsByType[FIELD_DATA_TYPES.STRING];

    // Filter COMPARISON_OPERATORS to only include allowed ones
    return COMPARISON_OPERATORS.filter(op => allowedOperatorValues.includes(op.value));
};

/**
 * Infer data type from Laravel column type
 */
export const inferDataTypeFromColumn = (columnType) => {
    const type = columnType.toLowerCase();

    if (['string', 'char', 'varchar', 'text', 'mediumtext', 'longtext'].includes(type)) {
        return FIELD_DATA_TYPES.STRING;
    }
    if (['integer', 'int', 'tinyint', 'smallint', 'mediumint', 'bigint'].includes(type)) {
        return FIELD_DATA_TYPES.INTEGER;
    }
    if (['float', 'double', 'decimal'].includes(type)) {
        return FIELD_DATA_TYPES.FLOAT;
    }
    if (['boolean', 'bool'].includes(type)) {
        return FIELD_DATA_TYPES.BOOLEAN;
    }
    if (type === 'date') {
        return FIELD_DATA_TYPES.DATE;
    }
    if (['datetime', 'timestamp'].includes(type)) {
        return FIELD_DATA_TYPES.DATETIME;
    }
    if (type === 'time') {
        return FIELD_DATA_TYPES.TIME;
    }
    if (['json', 'jsonb'].includes(type)) {
        return FIELD_DATA_TYPES.JSON;
    }
    if (type === 'array') {
        return FIELD_DATA_TYPES.ARRAY;
    }

    return FIELD_DATA_TYPES.STRING;
};

/**
 * Infer data type from field name patterns
 */
export const inferDataTypeFromFieldName = (fieldName) => {
    const name = fieldName.toLowerCase();

    // Email patterns
    if (name.includes('email')) {
        return FIELD_DATA_TYPES.EMAIL;
    }

    // URL patterns
    if (name.includes('url') || name.includes('link') || name.includes('website')) {
        return FIELD_DATA_TYPES.URL;
    }

    // UUID patterns
    if (name.includes('uuid')) {
        return FIELD_DATA_TYPES.UUID;
    }

    // Date patterns
    if (name.endsWith('_at') || name.endsWith('_date')) {
        return FIELD_DATA_TYPES.DATETIME;
    }

    // Boolean patterns
    if (name.startsWith('is_') || name.startsWith('has_') || name.startsWith('can_')) {
        return FIELD_DATA_TYPES.BOOLEAN;
    }

    // Integer patterns (IDs)
    if (name.endsWith('_id') || name === 'id') {
        return FIELD_DATA_TYPES.INTEGER;
    }

    // Default to string
    return FIELD_DATA_TYPES.STRING;
};

/**
 * Get HTML input type for a data type
 */
export const getInputType = (dataType, datePart = null) => {
    // If we are comparing a date part (year, month, day), the input is always a number
    if (datePart) {
        return 'number';
    }

    const inputTypes = {
        [FIELD_DATA_TYPES.STRING]: 'text',
        [FIELD_DATA_TYPES.EMAIL]: 'email',
        [FIELD_DATA_TYPES.URL]: 'url',
        [FIELD_DATA_TYPES.UUID]: 'text',
        [FIELD_DATA_TYPES.NUMBER]: 'number',
        [FIELD_DATA_TYPES.INTEGER]: 'number',
        [FIELD_DATA_TYPES.FLOAT]: 'number',
        [FIELD_DATA_TYPES.BOOLEAN]: 'checkbox',
        [FIELD_DATA_TYPES.DATE]: 'date',
        [FIELD_DATA_TYPES.DATETIME]: 'datetime-local',
        [FIELD_DATA_TYPES.TIME]: 'time',
        [FIELD_DATA_TYPES.ARRAY]: 'textarea',
        [FIELD_DATA_TYPES.JSON]: 'textarea',
        [FIELD_DATA_TYPES.OBJECT]: 'textarea',
    };
    return inputTypes[dataType] || 'text';
};

/**
 * Check if data type supports list input (comma-separated values)
 */
export const supportsListInput = (dataType) => {
    return [
        FIELD_DATA_TYPES.STRING,
        FIELD_DATA_TYPES.NUMBER,
        FIELD_DATA_TYPES.INTEGER,
        FIELD_DATA_TYPES.FLOAT,
        FIELD_DATA_TYPES.EMAIL,
        FIELD_DATA_TYPES.URL,
        FIELD_DATA_TYPES.UUID,
    ].includes(dataType);
};

/**
 * Get placeholder text for input based on data type and operator
 */
export const getPlaceholder = (dataType, operator, datePart = null) => {
    if (datePart) {
        const partPlaceholders = {
            [DATE_PARTS.YEAR]: '2025',
            [DATE_PARTS.MONTH]: '1-12',
            [DATE_PARTS.DAY]: '1-31',
            [DATE_PARTS.HOUR]: '0-23',
            [DATE_PARTS.MINUTE]: '0-59',
        };
        return partPlaceholders[datePart] || 'Enter value...';
    }

    if (operator === 'IN' || operator === 'NOT IN') {
        const placeholders = {
            [FIELD_DATA_TYPES.INTEGER]: '1, 2, 5',
            [FIELD_DATA_TYPES.NUMBER]: '1.5, 2.7, 3.14',
            [FIELD_DATA_TYPES.FLOAT]: '1.5, 2.7, 3.14',
            [FIELD_DATA_TYPES.STRING]: 'value1, value2, value3',
            [FIELD_DATA_TYPES.EMAIL]: 'email1@example.com, email2@example.com',
            [FIELD_DATA_TYPES.URL]: 'https://example1.com, https://example2.com',
            [FIELD_DATA_TYPES.UUID]: 'uuid1, uuid2, uuid3',
        };
        return placeholders[dataType] || 'Comma-separated values';
    }

    const placeholders = {
        [FIELD_DATA_TYPES.STRING]: 'Enter text...',
        [FIELD_DATA_TYPES.NUMBER]: 'Enter number...',
        [FIELD_DATA_TYPES.INTEGER]: 'Enter number...',
        [FIELD_DATA_TYPES.FLOAT]: 'Enter decimal...',
        [FIELD_DATA_TYPES.BOOLEAN]: 'true/false',
        [FIELD_DATA_TYPES.DATE]: 'YYYY-MM-DD',
        [FIELD_DATA_TYPES.DATETIME]: 'YYYY-MM-DD HH:MM:SS',
        [FIELD_DATA_TYPES.TIME]: 'HH:MM:SS',
        [FIELD_DATA_TYPES.EMAIL]: 'email@example.com',
        [FIELD_DATA_TYPES.URL]: 'https://example.com',
        [FIELD_DATA_TYPES.UUID]: 'xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx',
    };
    return placeholders[dataType] || 'Enter value...';
};

export default FIELD_DATA_TYPES;
