/**
 * Input field styles (text, textarea, etc.)
 *
 * Tailwind cannot see `ring-${color}` in template literals — those classes are not in the CSS
 * bundle and the browser falls back to a black focus ring. Use full class strings below.
 */
const INPUT_FOCUS_NEUTRAL =
    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-slate-400/35 dark:focus-visible:ring-slate-500/45 focus-visible:border-slate-400 dark:focus-visible:border-slate-500';

/** Keys = node accent colors (BaseNodeContainer + fallbacks). */
const INPUT_FOCUS_BY_COLOR = {
    slate: INPUT_FOCUS_NEUTRAL,
    gray: 'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gray-400/35 dark:focus-visible:ring-gray-500/45 focus-visible:border-gray-400 dark:focus-visible:border-gray-500',
    amber:
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-500/30 dark:focus-visible:ring-amber-400/35 focus-visible:border-amber-500 dark:focus-visible:border-amber-400',
    blue: 'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500/30 dark:focus-visible:ring-blue-400/35 focus-visible:border-blue-500 dark:focus-visible:border-blue-400',
    yellow:
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-yellow-500/35 dark:focus-visible:ring-yellow-400/40 focus-visible:border-yellow-500 dark:focus-visible:border-yellow-400',
    emerald:
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/30 dark:focus-visible:ring-emerald-400/35 focus-visible:border-emerald-500 dark:focus-visible:border-emerald-400',
    purple:
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-purple-500/30 dark:focus-visible:ring-purple-400/35 focus-visible:border-purple-500 dark:focus-visible:border-purple-400',
    violet:
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-500/30 dark:focus-visible:ring-violet-400/35 focus-visible:border-violet-500 dark:focus-visible:border-violet-400',
    cyan: 'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-500/30 dark:focus-visible:ring-cyan-400/35 focus-visible:border-cyan-500 dark:focus-visible:border-cyan-400',
    orange:
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-500/30 dark:focus-visible:ring-orange-400/35 focus-visible:border-orange-500 dark:focus-visible:border-orange-400',
    rose: 'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-rose-500/30 dark:focus-visible:ring-rose-400/35 focus-visible:border-rose-500 dark:focus-visible:border-rose-400',
    indigo:
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500/30 dark:focus-visible:ring-indigo-400/35 focus-visible:border-indigo-500 dark:focus-visible:border-indigo-400',
    teal: 'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-teal-500/30 dark:focus-visible:ring-teal-400/35 focus-visible:border-teal-500 dark:focus-visible:border-teal-400',
    pink: 'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-pink-500/30 dark:focus-visible:ring-pink-400/35 focus-visible:border-pink-500 dark:focus-visible:border-pink-400',
    green:
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-green-500/30 dark:focus-visible:ring-green-400/35 focus-visible:border-green-500 dark:focus-visible:border-green-400',
    red: 'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-500/30 dark:focus-visible:ring-red-400/35 focus-visible:border-red-500 dark:focus-visible:border-red-400',
};

const inputFocusFor = (color) => INPUT_FOCUS_BY_COLOR[color] ?? INPUT_FOCUS_BY_COLOR.cyan;

const INPUT_BASE =
    'w-full px-3 py-1.5 text-xs border border-slate-200 dark:border-slate-700 rounded-lg bg-white dark:bg-slate-900/80 text-slate-900 dark:text-slate-100 transition-colors outline-none';

export const INPUT_STYLES = {
    BASE: `${INPUT_BASE} ${INPUT_FOCUS_NEUTRAL}`,

    withColor: (color) => `${INPUT_BASE} ${inputFocusFor(color)}`,
};

/**
 * Select field styles (NO GLOSSY EFFECT!)
 */
const SELECT_BASE =
    'w-full px-3 py-1.5 text-xs border border-slate-200 dark:border-slate-700 rounded-lg bg-white dark:bg-slate-900 text-slate-900 dark:text-slate-100 transition-colors cursor-pointer outline-none';

export const SELECT_STYLES = {
    BASE: `${SELECT_BASE} ${INPUT_FOCUS_NEUTRAL}`,

    withColor: (color) => `${SELECT_BASE} ${inputFocusFor(color)}`,
};

