import React from 'react';
import { TYPOGRAPHY, INPUT_STYLES, SELECT_STYLES, SPACING, NODE_DIVIDER } from '../../constants/uiStyles';

/**
 * Dynamic Input Wrapper
 * Adds a lightning button inside the input to toggle dynamic mode
 */
export const DynamicInputWrapper = ({ children, isDynamic, onToggle }) => {
    return (
        <div className="relative group/dynamic w-full">
            {children}
            {onToggle && (
                <button
                    type="button"
                    onClick={onToggle}
                    title={isDynamic ? 'Use manual input' : 'Use dynamic value (e.g. {{variable}} or now())'}
                    className={`absolute right-1 top-1/2 -translate-y-1/2 z-10 text-[10px] px-1.5 py-0.5 rounded transition-all ${
                        isDynamic
                            ? 'bg-amber-100/90 text-amber-700 hover:bg-amber-200 dark:bg-amber-900/60 dark:text-amber-400'
                            : 'bg-transparent text-slate-400 hover:bg-slate-200 hover:text-amber-600 opacity-40 group-hover/dynamic:opacity-100 dark:text-slate-500 dark:hover:bg-slate-700 dark:hover:text-amber-400'
                    }`}
                >
                    ⚡
                </button>
            )}
        </div>
    );
};

/**
 * Standardized Field Label
 */
export const FieldLabel = ({ children, required = false }) => (
    <label className={TYPOGRAPHY.LABEL.className}>
        {children}
        {required && <span className="text-rose-500 ml-0.5">*</span>}
    </label>
);

/**
 * Standardized Text Input
 */
export const TextInput = ({
    value,
    onChange,
    placeholder = '',
    color = 'slate',
    className = '',
    ...props
}) => {
    const baseClass = color === 'slate'
        ? INPUT_STYLES.BASE
        : INPUT_STYLES.withColor(color);

    return (
        <input
            type="text"
            value={value}
            onChange={onChange}
            placeholder={placeholder}
            className={`${baseClass} ${className}`}
            {...props}
        />
    );
};

/**
 * Standardized Select Input (NO GLOSSY!)
 */
export const SelectInput = ({
    value,
    onChange,
    options = [],
    placeholder = 'Select...',
    color = 'slate',
    className = '',
    ...props
}) => {
    const baseClass = color === 'slate'
        ? SELECT_STYLES.BASE
        : SELECT_STYLES.withColor(color);

    return (
        <select
            value={value}
            onChange={onChange}
            className={`${baseClass} ${className}`}
            {...props}
        >
            {placeholder && <option value="">{placeholder}</option>}
            {options
                .filter((opt) => !(placeholder && String(opt?.value ?? '') === ''))
                .map((opt) => (
                    <option key={String(opt.value)} value={opt.value}>
                        {opt.label}
                    </option>
                ))}
        </select>
    );
};

/**
 * Standardized Textarea
 */
export const TextareaInput = ({
    value,
    onChange,
    placeholder = '',
    color = 'slate',
    rows = 3,
    className = '',
    ...props
}) => {
    const baseClass = color === 'slate'
        ? INPUT_STYLES.BASE
        : INPUT_STYLES.withColor(color);

    return (
        <textarea
            value={value}
            onChange={onChange}
            placeholder={placeholder}
            rows={rows}
            className={`${baseClass} resize-none ${className}`}
            {...props}
        />
    );
};

/**
 * Node Config Fields (Name + Description)
 * These fields should be present in ALL nodes
 */
export const NodeConfigFields = ({
    label,
    description,
    onLabelChange,
    onDescriptionChange,
    labelPlaceholder = 'Node name',
    descriptionPlaceholder = 'Description (optional)',
    color = 'slate',
    readOnly = false,
}) => {
    return (
        <div className={`p-4 space-y-4 ${NODE_DIVIDER.AFTER_CONFIG}`}>
            <div className="grid grid-cols-2 gap-3">
                <div className={SPACING.FIELD_GAP}>
                    <FieldLabel>Node Title</FieldLabel>
                    <TextInput
                        value={label}
                        onChange={onLabelChange}
                        placeholder={labelPlaceholder}
                        color={color}
                        readOnly={readOnly}
                        disabled={readOnly}
                    />
                </div>
                <div className={SPACING.FIELD_GAP}>
                    <FieldLabel>Description</FieldLabel>
                    <TextInput
                        value={description}
                        onChange={onDescriptionChange}
                        placeholder={descriptionPlaceholder}
                        color={color}
                        className="placeholder:italic"
                        readOnly={readOnly}
                        disabled={readOnly}
                    />
                </div>
            </div>
        </div>
    );
};
