import React from 'react';
import { useNodeAccessUi } from '../../hooks/useNodeAccessUi';
import { NodeReadOnlyBanner } from './NodeReadOnlyBanner';

export function NodeNonExecutableNotice({ data }) {
    const { executable, nonExecutableHint } = useNodeAccessUi(data);

    if (executable) {
        return null;
    }

    return (
        <NodeReadOnlyBanner
            message={
                nonExecutableHint
                ?? 'Questo nodo è disabilitato in esecuzione per il tuo ruolo.'
            }
        />
    );
}

