import React from 'react';
import { useNodeAccessUi } from '../../hooks/useNodeAccessUi';
import { NodeReadOnlyBanner } from './NodeReadOnlyBanner';

/**
 * Standard read-only banner when `nodeAccess.configReadOnly` is set (whitelabel).
 * Place at the top of the expanded node body (inside `.nodrag`).
 */
export function NodeConfigReadOnlyNotice({ data }) {
    const { configReadOnlyByPolicy, readOnlyHint } = useNodeAccessUi(data);

    // Show this notice only when the node is explicitly marked read-only by policy.
    // Workflow-level read-only is communicated at the editor level.
    if (!configReadOnlyByPolicy) {
        return null;
    }

    return <NodeReadOnlyBanner message={readOnlyHint} />;
}
