/**
 * Voodflow Editor Configuration Constants
 * 
 * Global configuration values for the Voodflow editor.
 * These values are not user-configurable and should be consistent across all nodes.
 */

/**
 * Debounce delay for auto-saving node configurations (in milliseconds)
 * 
 * This delay is applied when users type in input fields to prevent
 * excessive backend calls. A longer delay provides smoother typing
 * experience but slightly delays the save operation.
 * 
 * @constant {number}
 * @default 1200
 */
export const NODE_CONFIG_DEBOUNCE_MS = 1200;

/**
 * Z-index for expanded nodes
 * 
 * When a node is expanded, it should appear above other nodes
 * to prevent UI elements from being hidden.
 * 
 * @constant {number}
 * @default 1000
 */
export const EXPANDED_NODE_Z_INDEX = 1000;

/**
 * Z-index for node menus (e.g., Add Node menu)
 * 
 * Menus should appear above expanded nodes.
 * 
 * @constant {number}
 * @default 3000
 */
export const NODE_MENU_Z_INDEX = 3000;

/**
 * Maximum number of expressions allowed in ExpressionNode
 * 
 * @constant {number}
 * @default 50
 */
export const MAX_EXPRESSIONS_PER_NODE = 50;

/**
 * Maximum number of validation rules in ValidateSchemaNode
 * 
 * @constant {number}
 * @default 20
 */
export const MAX_VALIDATION_RULES = 20;
