import React from 'react';
import { EXPANDED_NODE_Z_INDEX } from '../../constants/editorConfig';

/**
 * Base Node Container Component
 *
 * Standardized container for all nodes with consistent:
 * - Hover effects (border color changes)
 * - Selection state (border color + glow)
 * - Size constraints
 * - Z-index management
 * - Dark mode support
 *
 * Usage:
 * ```jsx
 * <BaseNodeContainer
 *   color="cyan"
 *   selected={selected}
 *   isExpanded={isExpanded}
 *   minWidth="320px"
 *   maxWidth="450px"
 * >
 *   {children}
 * </BaseNodeContainer>
 * ```
 *
 * @param {string} color - Node color (e.g., 'amber', 'teal', 'cyan', 'emerald', 'blue', 'purple', 'pink', 'rose')
 * @param {boolean} selected - Whether the node is currently selected
 * @param {boolean} isExpanded - Whether the node is expanded (for z-index management)
 * @param {string} minWidth - Minimum width (default: '320px')
 * @param {string} maxWidth - Maximum width (default: '450px')
 * @param {object} style - Additional inline styles
 * @param {string} className - Additional CSS classes
 * @param {React.ReactNode} children - Node content
 */
export const BaseNodeContainer = ({
    color = 'cyan',
    selected = false,
    isExpanded = false,
    minWidth = '320px',
    maxWidth = '450px',
    style = {},
    className = '',
    children
}) => {
    // Standard width for closed nodes: 350px (like Read Data)
    // When expanded, use the provided minWidth/maxWidth
    const collapsedWidth = '350px';
    const finalMinWidth = isExpanded ? minWidth : collapsedWidth;
    const finalMaxWidth = isExpanded ? maxWidth : collapsedWidth;
    // Map colors to Tailwind classes (must be static for Tailwind to include them)
    const colorMap = {
        amber: {
            selected: 'border-amber-500 shadow-amber-500/20',
            hover: 'hover:border-amber-400 dark:hover:border-amber-600'
        },
        blue: {
            selected: 'border-blue-500 shadow-blue-500/20',
            hover: 'hover:border-blue-400 dark:hover:border-blue-600'
        },
        yellow: {
            selected: 'border-yellow-500 shadow-yellow-500/20',
            hover: 'hover:border-yellow-400 dark:hover:border-yellow-600'
        },
        emerald: {
            selected: 'border-emerald-500 shadow-emerald-500/20',
            hover: 'hover:border-emerald-400 dark:hover:border-emerald-600'
        },
        purple: {
            selected: 'border-purple-500 shadow-purple-500/20',
            hover: 'hover:border-purple-400 dark:hover:border-purple-600'
        },
        violet: {
            selected: 'border-violet-500 shadow-violet-500/20',
            hover: 'hover:border-violet-400 dark:hover:border-violet-600'
        },
        slate: {
            selected: 'border-slate-500 shadow-slate-500/20',
            hover: 'hover:border-slate-400 dark:hover:border-slate-600'
        },
        gray: {
            selected: 'border-gray-500 shadow-gray-500/20',
            hover: 'hover:border-gray-400 dark:hover:border-gray-600'
        },
        cyan: {
            selected: 'border-cyan-500 shadow-cyan-500/20',
            hover: 'hover:border-cyan-400 dark:hover:border-cyan-600'
        },
        orange: {
            selected: 'border-orange-500 shadow-orange-500/20',
            hover: 'hover:border-orange-400 dark:hover:border-orange-600'
        },
        rose: {
            selected: 'border-rose-500 shadow-rose-500/20',
            hover: 'hover:border-rose-400 dark:hover:border-rose-600'
        },
        indigo: {
            selected: 'border-indigo-500 shadow-indigo-500/20',
            hover: 'hover:border-indigo-400 dark:hover:border-indigo-600'
        }
    };

    const colorClasses = colorMap[color] || colorMap.cyan;

    // Build the complete class string with dynamic color and states
    const containerClasses = `
        relative
        bg-white dark:bg-slate-900
        border-2
        rounded-xl
        shadow-lg
        transition-all duration-200
        group
        ${selected
            ? colorClasses.selected
            : `border-slate-200 dark:border-slate-700 ${colorClasses.hover}`
        }
        ${className}
    `.trim().replace(/\s+/g, ' ');

    // Combine z-index management with custom styles
    const containerStyle = {
        zIndex: isExpanded ? EXPANDED_NODE_Z_INDEX : 'auto',
        minWidth: finalMinWidth,
        maxWidth: finalMaxWidth,
        ...style
    };

    return (
        <div className={containerClasses} style={containerStyle}>
            {children}
        </div>
    );
};

/**
 * Color variants helper
 *
 * Pre-defined color schemes for common node types:
 * - Data nodes: cyan
 * - Logic nodes: amber
 * - Action nodes: emerald
 * - Trigger nodes: blue
 * - Transform nodes: purple
 * - Error handling: rose
 */
export const NODE_COLORS = {
    DATA: 'cyan',
    LOGIC: 'amber',
    ACTION: 'emerald',
    TRIGGER: 'blue',
    TRANSFORM: 'purple',
    ERROR: 'rose',
    UTILITY: 'teal',
    WEBHOOK: 'pink'
};
