import React, { useState } from 'react';

/**
 * Help Tooltip Component
 * 
 * A subtle, non-invasive tooltip that can be placed anywhere to provide contextual help.
 * Shows on hover with a smooth animation.
 * 
 * @param {string} content - The help text to display
 * @param {string} position - Position of the tooltip: 'top', 'bottom', 'left', 'right' (default: 'top')
 * @param {string} className - Additional classes for the trigger icon
 */
export const HelpTooltip = ({ content, position = 'top', className = '' }) => {
    const [isVisible, setIsVisible] = useState(false);

    const positionClasses = {
        top: 'bottom-full left-1/2 -translate-x-1/2 mb-2',
        bottom: 'top-full left-1/2 -translate-x-1/2 mt-2',
        left: 'right-full top-1/2 -translate-y-1/2 mr-2',
        right: 'left-full top-1/2 -translate-y-1/2 ml-2'
    };

    const arrowClasses = {
        top: 'top-full left-1/2 -translate-x-1/2 border-l-transparent border-r-transparent border-b-transparent border-t-slate-800 dark:border-t-slate-700',
        bottom: 'bottom-full left-1/2 -translate-x-1/2 border-l-transparent border-r-transparent border-t-transparent border-b-slate-800 dark:border-b-slate-700',
        left: 'left-full top-1/2 -translate-y-1/2 border-t-transparent border-b-transparent border-r-transparent border-l-slate-800 dark:border-l-slate-700',
        right: 'right-full top-1/2 -translate-y-1/2 border-t-transparent border-b-transparent border-l-transparent border-r-slate-800 dark:border-r-slate-700'
    };

    return (
        <div className={`relative inline-flex ${className}`}>
            {/* Trigger Icon */}
            <button
                type="button"
                onMouseEnter={() => setIsVisible(true)}
                onMouseLeave={() => setIsVisible(false)}
                className="w-4 h-4 flex items-center justify-center rounded-full text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 transition-colors cursor-help"
                aria-label="Help"
            >
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
            </button>

            {/* Tooltip */}
            {isVisible && (
                <div
                    className={`absolute z-50 ${positionClasses[position]} pointer-events-none`}
                    style={{ minWidth: '200px', maxWidth: '300px' }}
                >
                    {/* Tooltip content */}
                    <div className="bg-slate-800 dark:bg-slate-700 text-white text-xs px-3 py-2 rounded-lg shadow-lg border border-slate-700 dark:border-slate-600">
                        {content}
                    </div>

                    {/* Arrow */}
                    <div className={`absolute w-0 h-0 border-4 ${arrowClasses[position]}`}></div>
                </div>
            )}
        </div>
    );
};

/**
 * Get help text for different operators
 */
export const getOperatorHelpText = (operator) => {
    const helpTexts = {
        'in': 'Enter values separated by commas. Example: 1,2,3 or apple,banana,orange',
        'not_in': 'Enter values separated by commas. Example: 1,2,3 or apple,banana,orange',
        'between': 'Enter two values separated by a comma. Example: 10,100',
        'contains': 'Enter text to search for. Case-insensitive partial match.',
        'not_contains': 'Enter text that should NOT be found in the field.',
        'starts_with': 'Enter text that the field should start with.',
        'ends_with': 'Enter text that the field should end with.',
        'is_null': 'No value needed. Checks if field is NULL.',
        'is_not_null': 'No value needed. Checks if field is NOT NULL.',
        'is_empty': 'No value needed. Checks if field is empty (NULL or empty string).',
        'is_not_empty': 'No value needed. Checks if field is NOT empty.',
        'equals': 'Enter exact value to match.',
        'not_equals': 'Enter value that should NOT match.',
        'greater_than': 'Enter number. Field must be greater than this value.',
        'greater_than_or_equal': 'Enter number. Field must be greater than or equal to this value.',
        'less_than': 'Enter number. Field must be less than this value.',
        'less_than_or_equal': 'Enter number. Field must be less than or equal to this value.',
        'is_true': 'No value needed. Checks if field is TRUE.',
        'is_false': 'No value needed. Checks if field is FALSE.',
        'older_than': 'Enter number of days. Example: 30 for records older than 30 days.',
        'newer_than': 'Enter number of days. Example: 7 for records newer than 7 days.',
        'in_last': 'Enter time period. Example: "7 days" or "2 weeks".',
        'in_next': 'Enter time period. Example: "7 days" or "2 weeks".',
    };

    return helpTexts[operator] || 'Enter the value to compare against.';
};
