/* eslint-disable react/prop-types */
import React, { useState, useEffect } from 'react';
import { FieldLabel, TextInput, SelectInput, DynamicInputWrapper } from './FormFields';
import { HelpTooltip, getOperatorHelpText } from './HelpTooltip';
import { RepeaterItem } from './RepeaterComponents';
import { useUpstreamFieldValues } from '../../hooks/useUpstreamFieldValues';
import {
    getOperatorsForDataType,
    inferDataTypeFromFieldName,
    inferDataTypeFromColumn,
    getInputType,
    getPlaceholder,
    FIELD_DATA_TYPES
} from '../../constants/dataTypes';

// Smart Logic Helpers
const getFieldDef = (fieldName, availableFields) => {
    if (!availableFields) return null;
    return availableFields.find(f => (typeof f === 'object' ? f.name : f) === fieldName);
};

const getFieldType = (fieldName, availableFields) => {
    const def = getFieldDef(fieldName, availableFields);
    if (def && typeof def === 'object') {
        // Prefer enriched runtime type (from upstream JSON sampling) or explicit metadata.
        if (def.dataType) {
            return def.dataType;
        }
        if (def.type) {
            return inferDataTypeFromColumn(def.type);
        }
    }
    return inferDataTypeFromFieldName(fieldName || '');
};

const SmartConditionRow = ({
    condition,
    onUpdate,
    onDelete,
    availableFields = [],
    color = 'slate',
    modelClass = null,
    livewireId = null,
    nodeId = null,
    readOnly = false,
}) => {
    // Local state for relative date inputs
    // We parse "7 days" into amount="7" and unit="days"
    const [relativeAmount, setRelativeAmount] = useState('');
    const [relativeUnit, setRelativeUnit] = useState('days');

    // State for distinct values dropdown (from DB model)
    const [valueOptions, setValueOptions] = useState([]);
    const [loadingValues, setLoadingValues] = useState(false);
    // When true, bypass the dropdown and show a free-text input (for dynamic values like {{id}})
    const [dynamicMode, setDynamicMode] = useState(false);
    const isManualValueMode = () => condition.value_mode === 'manual';

    // Fallback: extract values from upstream JSON data when no DB model
    const upstreamValues = useUpstreamFieldValues(nodeId, condition.column);

    const isRelativeOperator = (op) => {
        return ['IN LAST', 'IN NEXT', 'OLDER THAN', 'NEWER THAN'].includes(op);
    };

    // Sync local state with condition.value when it changes from outside
    useEffect(() => {
        if (isRelativeOperator(condition.operator)) {
            const val = condition.value || '';
            const match = val.match(/^(\d+)\s*([a-zA-Z]+)$/);
            if (match) {
                setRelativeAmount(match[1]);
                // Normalize unit (e.g., 'days' from 'day')
                let unit = match[2].toLowerCase();
                if (!unit.endsWith('s')) unit += 's';
                setRelativeUnit(unit);
            }
        }
    }, [condition.value, condition.operator]);

    // Fetch distinct values when field changes
    useEffect(() => {
        // Preserve explicit mode across refreshes; fallback to legacy heuristic for old configs.
        setDynamicMode(isManualValueMode() || (typeof condition.value === 'string' && condition.value.includes('{{')));

        if (!condition.column || !modelClass || !livewireId) {
            setValueOptions([]);
            return;
        }

        setLoadingValues(true);

        try {
            const component = window.Livewire?.find(livewireId);
            if (!component) {
                console.warn('[SmartConditionRow] Livewire component not found');
                setLoadingValues(false);
                return;
            }

            // Livewire v3 uses call() with promise
            component.call('getFieldDistinctValues', {
                modelClass,
                field: condition.column
            }).then((response) => {
                if (response && response.success && response.values) {
                    const labels = response.labels || [];
                    setValueOptions(response.values.map((val, i) => ({
                        value: val?.toString() ?? '',
                        label: (labels[i] ?? val)?.toString() || '(empty)'
                    })));
                }
                setLoadingValues(false);
            }).catch((error) => {
                console.error('[SmartConditionRow] Error fetching field values:', error);
                setLoadingValues(false);
            });
        } catch (error) {
            console.error('[SmartConditionRow] Exception:', error);
            setLoadingValues(false);
        }
    }, [condition.column, modelClass, livewireId]);

    const handleRelativeChange = (amount, unit) => {
        setRelativeAmount(amount);
        setRelativeUnit(unit);

        // Construct string: "7 days"
        if (amount) {
            onUpdate('value', `${amount} ${unit}`);
        } else {
            onUpdate('value', '');
        }
    };

    // Determine types and operators
    const currentDataType = getFieldType(condition.column, availableFields);
    const validOperators = getOperatorsForDataType(currentDataType);

    // Check if operator needs text input (lists, etc)
    const isTextOperator = [
        'IN', 'NOT IN', 'BETWEEN',
        'LIKE', 'NOT LIKE', 'STARTS WITH', 'ENDS WITH'
    ].includes(condition.operator);

    // Determine input type
    const inputType = isTextOperator ? 'text' : getInputType(currentDataType);

    // Map available fields to options
    const fieldOptions = availableFields.map(field => {
        const value = typeof field === 'object' ? field.name : field;
        const label = typeof field === 'object' ? (field.label || field.name) : field;
        return { value, label };
    });

    // Operator options
    const operatorOptions = validOperators.map(op => ({
        value: op.value, // Use actual operator value (e.g. '=', 'OLDER THAN')
        label: op.label
    }));

    // Operators that don't need value input
    const noValueOperators = [
        'IS NULL', 'IS NOT NULL', 'IS EMPTY', 'IS NOT EMPTY',
        'IS TRUE', 'IS FALSE', // Boolean: value is implicit
        'TODAY', 'YESTERDAY', 'THIS WEEK', 'LAST WEEK',
        'THIS MONTH', 'LAST MONTH', 'THIS YEAR', 'LAST YEAR'
    ];

    // Boolean with = or !=: use dropdown (True/False) instead of checkbox
    const isBooleanValueOperator = currentDataType === FIELD_DATA_TYPES.BOOLEAN
        && ['=', '!='].includes(condition.operator);
    const booleanValueOptions = [
        { value: 'true', label: 'True' },
        { value: 'false', label: 'False' }
    ];

    return (
        <RepeaterItem onDelete={readOnly ? undefined : onDelete} color={color}>
            <div className="space-y-2">
                {/* Field Selection */}
                <div className="space-y-1">
                    <FieldLabel>Field</FieldLabel>
                    <SelectInput
                        value={condition.column || ''}
                        onChange={(e) => onUpdate('column', e.target.value)}
                        options={fieldOptions}
                        placeholder="Select field..."
                        color={color}
                        className="font-mono text-[11px]"
                        disabled={readOnly}
                    />
                </div>

                {/* Operator Selection */}
                <div className="space-y-1">
                    <FieldLabel>Operator</FieldLabel>
                    <SelectInput
                        value={condition.operator || 'equals'}
                        onChange={(e) => onUpdate('operator', e.target.value)}
                        options={operatorOptions}
                        color={color}
                        className="text-[11px]"
                        disabled={readOnly}
                    />
                </div>

                {/* Value Input */}
                {!noValueOperators.includes(condition.operator) && (
                    <div className="space-y-1">
                        <div className="flex items-center gap-1 mb-1">
                            <FieldLabel>Value</FieldLabel>
                            <HelpTooltip
                                content={getOperatorHelpText(condition.operator)}
                                position="right"
                            />
                        </div>

                        <DynamicInputWrapper
                            isDynamic={dynamicMode}
                            onToggle={
                                readOnly ? null : (
                                    (!isRelativeOperator(condition.operator) && !isBooleanValueOperator)
                                        ? () => {
                                            setDynamicMode((current) => {
                                                const next = !current;
                                                onUpdate('value_mode', next ? 'manual' : 'select');
                                                return next;
                                            });
                                        }
                                        : null
                                )
                            }
                        >
                            {isRelativeOperator(condition.operator) ? (
                                <div className="flex gap-2 w-full">
                                    <div className="flex-1">
                                        <TextInput
                                            type="number"
                                            value={relativeAmount}
                                            onChange={(e) => handleRelativeChange(e.target.value, relativeUnit)}
                                            placeholder="Amount"
                                            color={color}
                                            min="1"
                                            className="pr-8"
                                            readOnly={readOnly}
                                            disabled={readOnly}
                                        />
                                    </div>
                                    <div className="w-1/3 min-w-[100px]">
                                        <SelectInput
                                            value={relativeUnit}
                                            onChange={(e) => handleRelativeChange(relativeAmount, e.target.value)}
                                            options={[
                                                { value: 'days', label: 'Days' },
                                                { value: 'weeks', label: 'Weeks' },
                                                { value: 'months', label: 'Months' },
                                                { value: 'years', label: 'Years' },
                                            ]}
                                            color={color}
                                            disabled={readOnly}
                                        />
                                    </div>
                                </div>
                            ) : isBooleanValueOperator ? (
                                <SelectInput
                                    value={condition.value || ''}
                                    onChange={(e) => {
                                        onUpdate('value_mode', 'select');
                                        onUpdate('value', e.target.value);
                                    }}
                                    options={[
                                        { value: '', label: '-- Select --' },
                                        ...booleanValueOptions
                                    ]}
                                    placeholder="True or False"
                                    color={color}
                                    className="pr-8"
                                    disabled={readOnly}
                                />
                            ) : (valueOptions.length > 0 || upstreamValues.length > 0) && !isTextOperator && !dynamicMode ? (
                                (() => {
                                    const container = document.getElementById('react-flow-container');
                                    const selectPlaceholder = container?.dataset?.selectValuePlaceholder || 'Select a value';
                                    const options = valueOptions.length > 0 ? valueOptions : upstreamValues;
                                    return (
                                        <SelectInput
                                            value={condition.value || ''}
                                            onChange={(e) => {
                                                onUpdate('value_mode', 'select');
                                                onUpdate('value', e.target.value);
                                            }}
                                            options={[
                                                { value: '', label: `-- ${selectPlaceholder} --` },
                                                ...options
                                            ]}
                                            placeholder=""
                                            color={color}
                                            disabled={readOnly || loadingValues}
                                            className="pr-8"
                                        />
                                    );
                                })()
                            ) : (
                                <TextInput
                                    type={dynamicMode ? 'text' : (inputType === 'checkbox' ? 'text' : inputType)}
                                    value={condition.value || ''}
                                    onChange={(e) => {
                                        onUpdate('value_mode', 'manual');
                                        onUpdate('value', e.target.value);
                                    }}
                                    placeholder={dynamicMode ? '{{id}} or {{variable}}' : getPlaceholder(currentDataType, condition.operator)}
                                    color={color}
                                    disabled={readOnly || (loadingValues && !dynamicMode)}
                                    readOnly={readOnly}
                                    className="pr-8"
                                />
                            )}
                        </DynamicInputWrapper>
                    </div>
                )}
            </div>
        </RepeaterItem>
    );
};

export default SmartConditionRow;

