import React from 'react';
import { COLLAPSED_NODE_STYLES, NODE_DIVIDER } from '../../constants/uiStyles';

/**
 * Collapsed Node View Component
 *
 * Renders collapsed content by priority:
 * 1. Summary (actions, e.g. trigger "Run Workflow")
 * 2. Logo (new node or not connected)
 * 3. Description (configured node)
 * 4. "Click to configure" placeholder
 *
 * @param {boolean} shouldShowLogo - Show Voodflow logo when new or disconnected
 * @param {boolean} hasConfiguration - Node has configuration (description / custom data)
 * @param {string} description - Node description
 * @param {React.Component|string} summary - Summary or action (e.g. button, "3 fields mapped")
 * @param {React.Component} VoodflowLogo - Logo component
 * @param {boolean} noPadding - Omit padding on summary (flush buttons against borders)
 * @param {boolean} isTrigger - Triggers show "Configure" instead of "Connect data"
 */
export const CollapsedView = ({
    shouldShowLogo = false,
    hasConfiguration = false,
    description = '',
    summary = null,
    VoodflowLogo,
    noPadding = false,
    isTrigger = false
}) => {
    // Priority 1: if there is a summary, always show it (triggers with buttons/actions)
    if (summary) {
        if (typeof summary !== 'string') {
            if (noPadding) {
                return (
                    <div className={`bg-slate-50/50 dark:bg-slate-800/20 rounded-b-xl ${NODE_DIVIDER.SECTION}`}>
                        {summary}
                    </div>
                );
            }
            return (
                <div className={`bg-slate-50/50 dark:bg-slate-800/20 rounded-b-xl ${NODE_DIVIDER.SECTION} p-4`}>
                    {summary}
                </div>
            );
        }
        return (
            <div className={COLLAPSED_NODE_STYLES.CONTAINER}>
                <div className="text-center space-y-1">
                    <div className={COLLAPSED_NODE_STYLES.DESCRIPTION}>{summary}</div>
                </div>
            </div>
        );
    }

    // Priority 2: logo (new node or normal node without connection; triggers when not configured)
    if (shouldShowLogo) {
        return (
            <div className={COLLAPSED_NODE_STYLES.CONTAINER}>
                <div className={COLLAPSED_NODE_STYLES.CONNECT_MESSAGE}>
                    {VoodflowLogo && <VoodflowLogo className={COLLAPSED_NODE_STYLES.LOGO} />}
                    <div className="text-slate-500 dark:text-slate-400 font-medium text-sm">
                        {isTrigger ? 'Configure' : 'Connect data'}
                    </div>
                </div>
            </div>
        );
    }

    // Priority 3: description when configured
    if (hasConfiguration && description) {
        return (
            <div className={COLLAPSED_NODE_STYLES.CONTAINER}>
                <div className={COLLAPSED_NODE_STYLES.DESCRIPTION}>{description}</div>
            </div>
        );
    }

    // Priority 4: not configured
    return (
        <div className={COLLAPSED_NODE_STYLES.CONTAINER}>
            <div className={COLLAPSED_NODE_STYLES.PLACEHOLDER}>
                Click to configure
            </div>
        </div>
    );
};
