import React from 'react';

/**
 * NodeIcon Component
 * 
 * Displays either a Heroicon or a custom image logo based on node configuration.
 * 
 */
const NodeIcon = ({ node, className = "w-5 h-5" }) => {
    // If logo file is missing, use Voodflow logo
    if (node.logoMissing) {
        return <HeroIcon name="voodflow-logo" className={className} />;
    }

    // Priority 1: Image Logo (URL)
    const logoUrl = node.logoUrl || (node.display?.iconType === 'image' ? node.display?.logo : null);

    if (logoUrl) {
        return (
            <img
                src={logoUrl}
                alt={node.name || 'Node'}
                className={`${className} object-contain`}
                onError={(e) => {
                    console.warn(`Failed to load logo for ${node.name}:`, logoUrl);
                    e.target.style.display = 'none';
                }}
            />
        );
    }

    // Priority 2: Custom SVG Path from manifest
    const icon = node.icon || node.display?.icon || 'heroicon-o-cog-6-tooth';

    return <HeroIcon name={icon} className={className} />;
};

