import React from 'react';
import { Handle, Position } from '@xyflow/react';

/**
 * StandardHandle - Standardized ReactFlow Handle Component
 *
 * Provides consistent styling, positioning, and behavior for all node connection handles.
 *
 * @param {string} type - 'target' (input) or 'source' (output)
 * @param {string} position - Position.Left or Position.Right
 * @param {string} color - Tailwind color class (e.g., 'amber-500', 'blue-500', 'emerald-500')
 * @param {string} id - Optional handle ID for multiple handles
 * @param {string|number} top - Optional top position (e.g., '50%', '30%', '70%'). Defaults to '50%' for centered
 * @param {boolean} isConnected - Whether the handle is connected (affects opacity)
 * @param {object} style - Additional inline styles
 * @param {string} className - Additional CSS classes
 */
const StandardHandle = ({
    type = 'target',
    position = Position.Left,
    color = 'slate-500',
    id = null,
    top = '50%',
    isConnected = null, // null = always visible, true/false = control opacity
    style = {},
    className = '',
}) => {
    // Color mapping - use inline styles to avoid Tailwind dynamic class issues
    const colorMap = {
        'amber': '#f59e0b', 'amber-500': '#f59e0b',
        'blue': '#3b82f6', 'blue-500': '#3b82f6',
        'emerald': '#10b981', 'emerald-500': '#10b981',
        'yellow': '#eab308', 'yellow-500': '#eab308',
        'red': '#ef4444', 'red-500': '#ef4444',
        'orange': '#f97316', 'orange-500': '#f97316',
        'rose': '#f43f5e', 'rose-500': '#f43f5e',
        'purple': '#a855f7', 'purple-500': '#a855f7',
        'violet': '#8b5cf6', 'violet-500': '#8b5cf6',
        'indigo': '#6366f1', 'indigo-500': '#6366f1',
        'cyan': '#06b6d4', 'cyan-500': '#06b6d4',
        'gray': '#6b7280', 'gray-500': '#6b7280',
        'slate': '#64748b', 'slate-500': '#64748b',
    };

    // Get color value
    let colorValue = colorMap[color] || colorMap['slate-500'];
    if (color.startsWith('bg-')) {
        const colorKey = color.replace('bg-', '');
        colorValue = colorMap[colorKey] || colorMap['slate-500'];
    }

    // Build opacity class based on connection status.
    // Important: handles must remain clickable even when not connected.
    // Use reduced opacity instead of hiding them.
    let opacityClass = '';
    if (isConnected !== null) {
        opacityClass = isConnected
            ? 'opacity-100'
            : 'opacity-70 hover:opacity-100';
    }

    // React Flow handles positioning; we only pass visual styles and `top` for multiple handles
    const handleStyle = {
        top: top,
        backgroundColor: colorValue,
        borderColor: 'white',
        borderWidth: '2px',
        borderStyle: 'solid',
        ...style,
    };

    // Build className - rimuovo bgColorClass, uso backgroundColor inline
    const handleClassName = `!w-6 !h-6 !border-2 !border-white ${opacityClass} ${className}`.trim();

    return (
        <Handle
            id={id}
            type={type}
            position={position}
            className={handleClassName}
            style={handleStyle}
        />
    );
};

export default StandardHandle;
