import { useMemo } from 'react';
import { useNodes, useEdges } from '@xyflow/react';

/**
 * Navigate a dot-notation path through an object/array structure,
 * transparently iterating through arrays when encountered.
 *
 * Example: given { data: [{ status: "active" }, { status: "inactive" }] }
 * and path "data.status", returns ["active", "inactive"].
 */
const resolveFieldValues = (root, fieldPath) => {
    const parts = fieldPath.split('.');
    let current = [root];

    for (const part of parts) {
        const next = [];
        for (const item of current) {
            if (Array.isArray(item)) {
                for (const el of item) {
                    if (el && typeof el === 'object' && part in el) {
                        next.push(el[part]);
                    }
                }
            } else if (item && typeof item === 'object' && part in item) {
                next.push(item[part]);
            }
        }
        current = next;
        if (current.length === 0) break;
    }

    return current.filter(v => v !== null && v !== undefined && typeof v !== 'object' && !Array.isArray(v));
};

/**
 * Try to parse JSON content from an upstream node.
 */
const getNodeContent = (sourceNode) => {
    const content = sourceNode.data?.content || sourceNode.data?.config?.content;
    if (content) {
        try {
            return typeof content === 'string' ? JSON.parse(content) : content;
        } catch { /* ignore */ }
    }

    const payload = sourceNode.data?.config?.test_payload || sourceNode.data?.config?.sample_payload;
    if (payload) {
        try {
            return typeof payload === 'string' ? JSON.parse(payload) : payload;
        } catch { /* ignore */ }
    }

    return null;
};

/**
 * Hook to extract distinct values for a specific field from upstream node data.
 *
 * Inspects JSON content/payloads from upstream nodes and collects all unique
 * primitive values found at the given field path.
 *
 * Returns an array of { value, label } objects for use in select dropdowns.
 */
export const useUpstreamFieldValues = (nodeId, fieldPath) => {
    const nodes = useNodes();
    const edges = useEdges();

    return useMemo(() => {
        if (!fieldPath) return [];

        const getUpstreamNodes = (id, visited = new Set()) => {
            if (visited.has(id)) return [];
            visited.add(id);
            const incoming = edges.filter(e => e.target === id);
            const sources = [];
            incoming.forEach(edge => {
                const source = nodes.find(n => n.id === edge.source);
                if (source) {
                    sources.push(source);
                    sources.push(...getUpstreamNodes(source.id, visited));
                }
            });
            return sources;
        };

        const upstreamNodes = getUpstreamNodes(nodeId);

        for (const source of upstreamNodes) {
            const parsed = getNodeContent(source);
            if (!parsed) continue;

            const values = resolveFieldValues(parsed, fieldPath);
            if (values.length > 0) {
                const unique = [...new Set(values.map(v => String(v)))];
                unique.sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
                return unique.map(v => ({ value: v, label: v }));
            }
        }

        return [];
    }, [nodeId, fieldPath, nodes, edges]);
};
