import React from 'react';
import { NODE_HEADER_STYLES, BADGE_STYLES } from '../../constants/uiStyles';
import { HeroIcon } from '../NodeIcon';
import NodeIcon from '../NodeIcon';

/**
 * Standardized Node Header Component
 *
 * Used by all nodes to ensure consistent header styling and behavior.
 *
 * @param {string} color - Node color (e.g., 'amber', 'teal', 'cyan')
 * @param {string} icon - SVG path for the node icon (fallback if no nodeData)
 * @param {object} nodeData - Full node data object (for logo support)
 * @param {string} subtitle - Node type (e.g., 'CALCULATION', 'DATA TRANSFORMATION')
 * @param {string} title - Custom node title
 * @param {string} badge - Optional badge text (e.g., '3 RESULTS')
 * @param {boolean} isExpanded - Whether the node is expanded
 * @param {boolean} canExpand - Whether the expand button should be enabled
 * @param {function} onToggleExpand - Callback when expand/collapse is clicked
 * @param {function} onDelete - Callback when delete is clicked
 */
export const NodeHeader = ({
    color,
    icon,
    nodeData = null,
    subtitle,
    title,
    badge = null,
    isExpanded = false,
    canExpand = true,
    onToggleExpand,
    onDelete
}) => {
    // Map color to Tailwind gradient classes
    const colorClasses = {
        amber: 'bg-gradient-to-r from-amber-500 to-amber-600',
        blue: 'bg-gradient-to-r from-blue-500 to-blue-600',
        yellow: 'bg-gradient-to-r from-yellow-500 to-yellow-600',
        emerald: 'bg-gradient-to-r from-emerald-500 to-emerald-600',
        purple: 'bg-gradient-to-r from-purple-500 to-purple-600',
        violet: 'bg-gradient-to-r from-violet-500 to-violet-600',
        slate: 'bg-gradient-to-r from-slate-500 to-slate-600',
        gray: 'bg-gradient-to-r from-gray-500 to-gray-600',
        orange: 'bg-gradient-to-r from-orange-500 to-orange-600',
        rose: 'bg-gradient-to-r from-rose-500 to-rose-600',
        indigo: 'bg-gradient-to-r from-indigo-500 to-indigo-600',
        cyan: 'bg-gradient-to-r from-cyan-500 to-cyan-600',
    };

    const gradientClass = colorClasses[color] || colorClasses.slate;

    return (
        <div className={`${gradientClass} px-4 py-2.5 flex items-center justify-between overflow-hidden group`} style={{ borderTopLeftRadius: '10px', borderTopRightRadius: '10px' }}>
            {/* Left side: Icon + Title */}
            <div className="flex items-center gap-3">
                <div className={NODE_HEADER_STYLES.ICON_CONTAINER}>
                    {nodeData ? (
                        <NodeIcon node={nodeData} className={NODE_HEADER_STYLES.ICON} />
                    ) : (
                        <HeroIcon name={icon} className={NODE_HEADER_STYLES.ICON} />
                    )}
                </div>
                <div>
                    <div className={NODE_HEADER_STYLES.SUBTITLE}>{subtitle}</div>
                    <div className={NODE_HEADER_STYLES.TITLE}>{title}</div>
                </div>
            </div>

            {/* Right side: Badge + Actions */}
            <div className={NODE_HEADER_STYLES.ACTIONS_CONTAINER}>
                {badge && (
                    <div className="px-2 py-0.5 rounded-full bg-white/20 backdrop-blur-md border border-white/10 text-[10px] font-black text-white uppercase tracking-tighter">
                        {badge}
                    </div>
                )}

                <div className={NODE_HEADER_STYLES.DIVIDER}></div>

                <button
                    onClick={onToggleExpand}
                    className={NODE_HEADER_STYLES.EXPAND_BUTTON}
                    disabled={!canExpand}
                >
                    <svg
                        className={`w-4 h-4 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''} ${!canExpand ? 'opacity-50' : ''}`}
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                    >
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" />
                    </svg>
                </button>

                <button
                    onClick={onDelete}
                    className={NODE_HEADER_STYLES.DELETE_BUTTON}
                >
                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                </button>
            </div>
        </div>
    );
};
