import React from 'react';

/**
 * Shown when a node’s configuration is read-only for the current user (whitelabel).
 */
export function NodeReadOnlyBanner({ message }) {
    const text = message || "This node's configuration is read-only for your role.";

    return (
        <div className="mx-4 mt-3 mb-1 text-xs text-amber-800 dark:text-amber-200 font-medium bg-amber-50 dark:bg-amber-950/50 border border-amber-200 dark:border-amber-900 rounded-lg px-3 py-2">
            {text}
        </div>
    );
}
