import React from 'react';
import { REPEATER_STYLES, TYPOGRAPHY } from '../../constants/uiStyles';

/**
 * Repeater Container
 * 
 * Container for lists of items (conditions, mappings, expressions, etc.)
 * The container expands vertically without limits.
 */
export const RepeaterContainer = ({ children, maxHeight }) => {
    // Prevent zoom when scrolling inside the container (if maxHeight is set)
    const handleWheel = (e) => {
        if (maxHeight) {
            e.stopPropagation();
        }
    };

    return (
        <>
            <style dangerouslySetInnerHTML={{
                __html: `
                    .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                    .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                    .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
                    html.dark .custom-scrollbar::-webkit-scrollbar-thumb { background: #334155; }
                `
            }} />
            <div
                className={REPEATER_STYLES.CONTAINER}
                style={maxHeight ? { maxHeight } : {}}
                onWheel={handleWheel}
            >
                {children}
            </div>
        </>
    );
};

/**
 * Repeater Item
 * 
 * Individual item in a repeater list with hover delete button
 * 
 * @param {React.ReactNode} children - Item content
 * @param {function} onDelete - Delete callback
 * @param {string} color - Node color for hover effect
 */
export const RepeaterItem = ({ children, onDelete, color = 'slate' }) => {
    const itemClass = color === 'slate'
        ? REPEATER_STYLES.ITEM
        : REPEATER_STYLES.ITEM_WITH_HOVER(color);

    return (
        <div className={itemClass}>
            {onDelete && (
                <button
                    type="button"
                    onClick={onDelete}
                    className={REPEATER_STYLES.DELETE_BUTTON}
                    title="Remove"
                >
                    <svg className={REPEATER_STYLES.DELETE_ICON} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                </button>
            )}

            {/* Item content */}
            {children}
        </div>
    );
};

/**
 * Repeater Header
 * 
 * Header for repeater sections with title and add button
 */
export const RepeaterHeader = ({ title, onAdd, addLabel = 'Add', AddButton }) => {
    return (
        <div className="flex items-center justify-between px-1">
            <label className={TYPOGRAPHY.SECTION_HEADER.className}>{title}</label>
            {AddButton && (
                <AddButton
                    onClick={onAdd}
                    label={addLabel}
                />
            )}
        </div>
    );
};

/**
 * Empty Repeater State
 * 
 * Shows when a repeater has no items
 */
export const EmptyRepeaterState = ({ message = 'No items yet', onAdd, addLabel = 'Add first item' }) => {
    return (
        <div className="text-center py-8 border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-xl bg-slate-50/30 dark:bg-slate-900/10">
            <div className="text-slate-400 text-xs font-bold uppercase tracking-widest leading-none mb-2">
                {message}
            </div>
            {onAdd && (
                <button
                    onClick={onAdd}
                    className="text-[10px] text-amber-500 hover:text-amber-600 font-black uppercase tracking-wider"
                >
                    + {addLabel}
                </button>
            )}
        </div>
    );
};
